/*
 * Hand-rolled crypto with no crypto library symbols: only constants that
 * pqscope's fallback recognises. Built statically and stripped. Never run.
 */
#include <stdio.h>

/* The NIST P-256 field prime, big-endian (SEC 2, 2.4.2). */
static volatile const unsigned char p256_prime[32] = {
	0xff, 0xff, 0xff, 0xff, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
	0x00, 0x00, 0x00, 0x00, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
};

/* DER encoding of the ML-KEM-768 OID 2.16.840.1.101.3.4.4.2 (NIST CSOR). */
static volatile const unsigned char mlkem768_oid[11] = {
	0x06, 0x09, 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x04, 0x02,
};

int main(void) {
	printf("%d\n", p256_prime[3] + mlkem768_oid[10]);
	return 0;
}
